<main class="content-shell"><div class="page-heading"><div><p class="section-kicker">Preservação documental</p><h1>Arquivo</h1><p class="muted">Consulte os expedientes concluídos e arquivados.</p></div></div><?php if ($message): ?><div class="flash <?= htmlspecialchars($message['type'], ENT_QUOTES, 'UTF-8') ?>" role="status"><?= htmlspecialchars($message['message'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form class="search-bar" method="get" action="arquivo.php"><label for="search">Pesquisar por número, assunto, remetente, setor ou referência</label><div><input id="search" name="search" type="search" value="<?= htmlspecialchars($search, ENT_QUOTES, 'UTF-8') ?>" placeholder="Ex.: EXP-2026-001"><button type="submit">Pesquisar</button></div></form><section class="table-panel"><div class="panel-heading"><h2>Expedientes arquivados</h2><span><?= count($archives) ?> resultado(s)</span></div><div class="table-wrap"><table><thead><tr><th>Número</th><th>Assunto</th><th>Origem / destino</th><th>Referência</th><th>Arquivado por</th><th>Data</th><th>Ação</th></tr></thead><tbody><?php foreach ($archives as $archive): ?><tr><td><strong><?= htmlspecialchars($archive['reference_code'], ENT_QUOTES, 'UTF-8') ?></strong></td><td><?= htmlspecialchars($archive['subject'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($archive['origin'], ENT_QUOTES, 'UTF-8') ?><br><span class="table-secondary">→ <?= htmlspecialchars($archive['destination'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars($archive['archive_reference'] ?: 'Sem referência', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($archive['archived_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars(date('d/m/Y H:i', strtotime($archive['archived_at'])), ENT_QUOTES, 'UTF-8') ?></td><td><a class="table-link" href="arquivo-view.php?id=<?= (int) $archive['id'] ?>">Ver arquivo</a></td></tr><?php endforeach; ?><?php if (!$archives): ?><tr><td colspan="7" class="empty-state">